package com.example.networkservice.controller; import com.example.networkservice.model.*;import com.example.networkservice.service.ActivationService;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/activations") @Tag(name="eSIM activation") public class ActivationController{private final ActivationService service;public ActivationController(ActivationService s){service=s;}@PostMapping @Operation(summary="Queue an eSIM activation")public ResponseEntity<Activation>create(@Valid@RequestBody CreateActivationRequest q){return ResponseEntity.status(201).body(service.create(q));}@GetMapping @Operation(summary="List activations or find by order")public Object list(@RequestParam(required=false)String orderId){return orderId==null?service.list():service.byOrder(orderId);}}
